#ifndef POLY_H
#define POLY_H

#include <stdint.h>
#include <stddef.h>
#include "params.h"

/*
 * Polynomial representation in NewHope.
 * Array of N coefficients in Z_q, where q = 12289.
 */
typedef struct Polynomial {
    uint16_t coeffs[NEWHOPE_N];
} poly;

/*
 * Generate polynomial with uniformly random coefficients modulo q
 * expanded from a 32-byte seed using SHAKE-128 rejection sampling.
 */
void poly_uniform(poly *a, const unsigned char *seed);

/*
 * Sample polynomial from centered binomial distribution with parameter k=8
 * using random bytes generated by SHAKE-256(seed || nonce).
 */
void poly_sample(poly *r, const unsigned char *seed, unsigned char nonce);

/*
 * Coefficient-wise addition of two polynomials modulo q: r = a + b mod q
 */
void poly_add(poly *r, const poly *a, const poly *b);

/*
 * Coefficient-wise subtraction of two polynomials modulo q: r = a - b mod q
 */
void poly_sub(poly *r, const poly *a, const poly *b);

/*
 * In-place forward Number Theoretic Transform (NTT) on polynomial r.
 */
void poly_ntt(poly *r);

/*
 * In-place inverse Number Theoretic Transform (INTT) on polynomial r.
 */
void poly_invntt(poly *r);

/*
 * Pointwise multiplication of two polynomials in NTT domain:
 * r[i] = montgomery_reduce(a[i] * b[i])
 */
void poly_mul_pointwise(poly *r, const poly *a, const poly *b);

/*
 * Serialize polynomial into byte array (packs 14-bit coefficients).
 * Output size: NEWHOPE_POLYBYTES (1792 bytes for N=1024).
 */
void poly_tobytes(unsigned char *r, const poly *p);

/*
 * Deserialize byte array back into polynomial.
 * Input size: NEWHOPE_POLYBYTES (1792 bytes for N=1024).
 */
void poly_frombytes(poly *p, const unsigned char *r);

/*
 * Compress polynomial coefficients into 3-bit values.
 * Output size: NEWHOPE_POLYCOMPRESSEDBYTES (384 bytes for N=1024).
 */
void poly_compress(unsigned char *r, const poly *p);

/*
 * Decompress 3-bit values into polynomial coefficients modulo q.
 * Input size: NEWHOPE_POLYCOMPRESSEDBYTES (384 bytes for N=1024).
 */
void poly_decompress(poly *r, const unsigned char *a);

/*
 * Encode 32-byte message into polynomial coefficients.
 */
void poly_frommsg(poly *r, const unsigned char *msg);

/*
 * Decode polynomial coefficients back into 32-byte message.
 */
void poly_tomsg(unsigned char *msg, const poly *x);

#endif /* POLY_H */
